import * as React from "react"

function SmoothScaleFloatReveal({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="smooth-scale-float-reveal"
      className={className}
      dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Smooth Scale Reveal Demo</title>
  <link rel="stylesheet" href="styles.css">
  <style>
    /* Estilos demo */
    body { font-family: 'Segoe UI', sans-serif; margin: 0; background: #111; color: white; overflow-x: hidden; }
    h1 { text-align: center; margin-top: 50px; font-weight: 300; }

    /* Cajas para visualizar el efecto */
    .card {
        background: linear-gradient(135deg, #4b6cb7 0%, #182848 100%);
        min-height: 400px;
        margin: 50px auto;
        width: 80%;
        max-width: 800px;
        border-radius: 20px;
        display: flex;
        justify-content: center;
        align-items: center;
        font-size: 2rem;
        box-shadow: 0 10px 30px rgba(0,0,0,0.5);
    }
  </style>
</head>
<body>

  <h1>Scroll Down to see the Magic 👇</h1>

  <div class="card reveal">
    <span>✨ Floating Card 1</span>
  </div>

  <div class="card reveal">
    <span>🚀 Floating Card 2</span>
  </div>

  <div class="card reveal">
    <span>🎨 Floating Card 3</span>
  </div>


</body>
</html>" }}
      {...props}
    />
  )
}

export { SmoothScaleFloatReveal }
